  1	#!/usr/bin/env node
  2	/**
  3	 * Bootstrap the Zimmermann Contentful space.
  4	 *
  5	 * Creates environments, locales, per-environment API keys, and the production
  6	 * alias for the six-tier delivery pipeline. Idempotent — safe to re-run.
  7	 *
  8	 * Tier topology:
  9	 *   DEV (dev) → TEST (test) → OMS INT (sit) → STAGE (staging) → UAT (uat) → PROD (master / production alias)
 10	 *
 11	 * Usage:
 12	 *   npm run setup:contentful
 13	 *   npm run setup:contentful -- --dry-run
 14	 *
 15	 * Required env vars (via .env):
 16	 *   CONTENTFUL_MANAGEMENT_TOKEN, CONTENTFUL_SPACE_ID
 17	 */
 18	
 19	import {
 20	  checkEnv,
 21	  createClient,
 22	  pollForReady,
 23	  getExistingEnvironmentIds,
 24	  getExistingLocaleCodes,
 25	  log,
 26	} from './_shared.mjs';
 27	
 28	const DRY_RUN = process.argv.includes('--dry-run');
 29	
 30	if (DRY_RUN) console.log('\n🔍  DRY RUN — no changes will be made.\n');
 31	
 32	checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
 33	
 34	// Environments to create, cloned from master.
 35	// master is created automatically by Contentful.
 36	const TARGET_ENVIRONMENTS = ['dev', 'test', 'sit', 'staging', 'uat'];
 37	
 38	// Locales — codes match SFCC sites.js locale IDs exactly so no mapping is needed.
 39	// en (AU) is the default/fallback; all others fall back to en.
 40	const LOCALES = [
 41	  { code: 'en',    name: 'English (AU)',             default: true,  fallbackCode: null  },
 42	  { code: 'en-US', name: 'English (US)',              default: false, fallbackCode: 'en' },
 43	  { code: 'en-CA', name: 'English (US International)', default: false, fallbackCode: 'en' },
 44	  { code: 'en-GB', name: 'English (UK / EU)',         default: false, fallbackCode: 'en' },
 45	  { code: 'fr',    name: 'French (EU)',               default: false, fallbackCode: 'en' },
 46	  { code: 'it',    name: 'Italian (EU)',              default: false, fallbackCode: 'en' },
 47	  { code: 'es',    name: 'Spanish (EU)',              default: false, fallbackCode: 'en' },
 48	  { code: 'en-CH', name: 'English (EU International)', default: false, fallbackCode: 'en' },
 49	  { code: 'en-HK', name: 'English (HK)',              default: false, fallbackCode: 'en' },
 50	  { code: 'en-AE', name: 'English (ME)',              default: false, fallbackCode: 'en' },
 51	];
 52	
 53	// Aliases to create/maintain.
 54	// production alias is what the MRT production tier points to — flipping it
 55	// is the zero-downtime release mechanism. master is kept in sync with it.
 56	const ALIASES = ['production'];
 57	
 58	const results = {
 59	  environments: { created: [], skipped: [] },
 60	  locales: { created: [], skipped: [], failed: [] },
 61	  apiKeys: { created: [], skipped: [] },
 62	  aliases: { created: [], updated: [], skipped: [] },
 63	};
 64	
 65	/**
 66	 * Create any missing LOCALES in one environment. Idempotent — existing codes are skipped.
 67	 *
 68	 * Split out of main() and parameterised because locales do NOT propagate to an environment
 69	 * created before them: a clone inherits master's locales as they stood at clone time, and
 70	 * nothing back-fills afterwards. Provisioning master first fixes new clones; re-running this
 71	 * per target environment fixes the ones that already existed.
 72	 */
 73	async function provisionLocales(client, environmentId) {
 74	  const existing = await getExistingLocaleCodes(client, environmentId);
 75	  log.info(`Existing locales in '${environmentId}': ${existing.join(', ')}`);
 76	
 77	  for (const locale of LOCALES) {
 78	    if (existing.includes(locale.code)) {
 79	      log.skip(`Locale '${locale.code}' already exists in '${environmentId}'`);
 80	      results.locales.skipped.push(`${environmentId}/${locale.code}`);
 81	      continue;
 82	    }
 83	    if (DRY_RUN) {
 84	      log.info(`[dry-run] Would create locale '${locale.code}' (${locale.name}) in '${environmentId}'`);
 85	      results.locales.created.push(`${environmentId}/${locale.code}`);
 86	      continue;
 87	    }
 88	    const payload = {
 89	      name: locale.name,
 90	      code: locale.code,
 91	      // Non-default locales are optional: required-localized fields can publish with
 92	      // only 'en' set — translation is a separate, later pass through the translation
 93	      // app, not a precondition for publishing English content. fallbackCode above
 94	      // covers reads in the meantime.
 95	      optional: !locale.default,
 96	    };
 97	    // `default` is only ever asserted on master. The SDK POSTs it verbatim on create (it strips
 98	    // it on update, but not here), so sending `default: true` into an environment that already
 99	    // has a different default risks Contentful either rejecting the call or — worse — silently
100	    // demoting the incumbent, which changes what the CDA returns for unlocalized reads. A cloned
101	    // environment already inherits master's default, and a pre-existing environment's default is
102	    // not this script's to repoint.
103	    if (environmentId === 'master') payload.default = locale.default;
104	    if (locale.fallbackCode) payload.fallbackCode = locale.fallbackCode;
105	
106	    try {
107	      await client.locale.create({ environmentId }, payload);
108	      log.success(`Created locale '${locale.code}' (${locale.name}) in '${environmentId}'`);
109	      results.locales.created.push(`${environmentId}/${locale.code}`);
110	    } catch (err) {
111	      log.warn(
112	        `Failed to create locale '${locale.code}' in '${environmentId}': ${err.message ?? err}. Skipping — re-run later to retry.`,
113	      );
114	      results.locales.failed.push(`${environmentId}/${locale.code}`);
115	    }
116	  }
117	}
118	
119	async function main() {
120	  const client = createClient();
121	
122	  // ── 1. Locales in master ────────────────────────────────────────────────────
123	  // Before environments, deliberately: §2 clones from master, and a clone only inherits the
124	  // locales master had at clone time. Creating them after would leave every new environment
125	  // without them, which is what previously happened.
126	  log.section('Locales (master)');
127	  await provisionLocales(client, 'master');
128	
129	  // ── 2. Environments ─────────────────────────────────────────────────────────
130	  log.section('Environments');
131	
132	  const { items: envItems } = await client.environment.getMany({ query: { limit: 100 } });
133	  const existingById   = new Map(envItems.map((e) => [e.sys.id, e]));
134	  const existingByName = new Map(envItems.map((e) => [e.name,   e]));
135	  log.info(`Existing: ${[...existingById.keys()].join(', ')}`);
136	
137	  // Environments that exist (or will) and are therefore safe to provision locales into below.
138	  // An orphaned-name environment is deliberately excluded — its real ID isn't the one we'd target.
139	  const provisionable = [];
140	
141	  for (const envId of TARGET_ENVIRONMENTS) {
142	    if (existingById.has(envId)) {
143	      log.skip(`Environment '${envId}' already exists`);
144	      results.environments.skipped.push(envId);
145	      provisionable.push(envId);
146	      continue;
147	    }
148	    // An environment with this name exists but was created with a wrong auto-generated ID
149	    // (can happen if a previous run failed mid-way using create() instead of createWithId())
150	    if (existingByName.has(envId)) {
151	      const orphan = existingByName.get(envId);
152	      log.warn(`Environment named '${envId}' exists with ID '${orphan.sys.id}'. Delete it in the Contentful web UI then re-run.`);
153	      results.environments.skipped.push(envId);
154	      continue;
155	    }
156	    if (DRY_RUN) {
157	      log.info(`[dry-run] Would create environment '${envId}' (clone of master)`);
158	      results.environments.created.push(envId);
159	      // Deliberately NOT pushed to `provisionable`: the environment does not exist, so reading
160	      // its locales in §3 would 404. It needs no back-fill anyway — a clone inherits master's
161	      // locales, which §1 has already completed by this point.
162	      continue;
163	    }
164	    log.info(`Creating environment '${envId}' (cloning from master)...`);
165	    // createWithId ensures the environment's API ID matches its name (e.g. 'dev' → ID 'dev')
166	    await client.environment.createWithId({ environmentId: envId }, { name: envId }, 'master');
167	    process.stdout.write('  Waiting for ready');
168	    await pollForReady(client, envId);
169	    console.log();
170	    log.success(`Environment '${envId}' ready`);
171	    results.environments.created.push(envId);
172	    provisionable.push(envId);
173	  }
174	
175	  // ── 3. Locales in the target environments ───────────────────────────────────
176	  // Environments cloned in §2 already inherited master's locales, so this is a no-op for them.
177	  // It exists for environments that pre-dated a locale being added to LOCALES — those never
178	  // receive it otherwise, because a clone only inherits once and nothing back-fills.
179	  log.section('Locales (target environments)');
180	
181	  for (const envId of provisionable) {
182	    await provisionLocales(client, envId);
183	  }
184	
185	  // ── 4. Per-environment API keys (Delivery + Preview) ────────────────────────
186	  log.section('API Keys');
187	
188	  const { items: existingKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
189	  const existingKeyNames = new Set(existingKeys.map((k) => k.name));
190	
191	  const allEnvs = ['master', ...TARGET_ENVIRONMENTS];
192	  for (const envId of allEnvs) {
193	    const tierLabel = envId === 'master' ? 'PRODUCTION' : envId.toUpperCase();
194	    const keyName = `Zimmermann ${tierLabel} — Delivery`;
195	
196	    if (existingKeyNames.has(keyName)) {
197	      log.skip(`API key '${keyName}' already exists`);
198	      results.apiKeys.skipped.push(envId);
199	      continue;
200	    }
201	    if (DRY_RUN) {
202	      log.info(`[dry-run] Would create API key '${keyName}'`);
203	      results.apiKeys.created.push(envId);
204	      continue;
205	    }
206	    await client.apiKey.create(
207	      {},
208	      {
209	        name: keyName,
210	        environments: [{ sys: { type: 'Link', linkType: 'Environment', id: envId } }],
211	      },
212	    );
213	    log.success(`Created API key '${keyName}'`);
214	    results.apiKeys.created.push(envId);
215	  }
216	
217	  // ── 5. Aliases ───────────────────────────────────────────────────────────────
218	  log.section('Aliases');
219	
220	  const { items: existingAliases } = await client.environmentAlias.getMany({});
221	  const existingAliasMap = Object.fromEntries(
222	    existingAliases.map((a) => [a.sys.id, a.environment.sys.id]),
223	  );
224	
225	  for (const aliasId of ALIASES) {
226	    const currentTarget = existingAliasMap[aliasId];
227	    if (currentTarget === 'master') {
228	      log.skip(`Alias '${aliasId}' already points to master`);
229	      results.aliases.skipped.push(aliasId);
230	      continue;
231	    }
232	    if (DRY_RUN) {
233	      const action = currentTarget ? `update (currently → ${currentTarget})` : 'create';
234	      log.info(`[dry-run] Would ${action} alias '${aliasId}' → master`);
235	      (currentTarget ? results.aliases.updated : results.aliases.created).push(aliasId);
236	      continue;
237	    }
238	    // The plain client has no createOrUpdate for environmentAlias — an existing alias
239	    // must go through update() (which needs its current sys.version), a new one through
240	    // createWithId().
241	    const targetLink = { environment: { sys: { type: 'Link', linkType: 'Environment', id: 'master' } } };
242	    if (currentTarget) {
243	      const existing = await client.environmentAlias.get({ environmentAliasId: aliasId });
244	      await client.environmentAlias.update({ environmentAliasId: aliasId }, { ...existing, ...targetLink });
245	    } else {
246	      await client.environmentAlias.createWithId({ environmentAliasId: aliasId }, targetLink);
247	    }
248	    const action = currentTarget ? 'Updated' : 'Created';
249	    log.success(`${action} alias '${aliasId}' → master`);
250	    (currentTarget ? results.aliases.updated : results.aliases.created).push(aliasId);
251	  }
252	
253	  // ── Summary ──────────────────────────────────────────────────────────────────
254	  console.log('\n╔══════════════════════════════════════╗');
255	  console.log('║  Bootstrap Summary                   ║');
256	  console.log('╚══════════════════════════════════════╝');
257	  console.log(`  Environments  created: [${results.environments.created.join(', ')}]  skipped: [${results.environments.skipped.join(', ')}]`);
258	  // skipped is now "<env>/<code>" across 6 environments, so in the steady state it is ~54
259	  // entries — a count reads better than the list. created/failed stay itemised: those are the
260	  // ones an operator has to act on.
261	  console.log(`  Locales       created: [${results.locales.created.join(', ')}]  skipped: ${results.locales.skipped.length}  failed: [${results.locales.failed.join(', ')}]`);
262	  console.log(`  API keys      created: [${results.apiKeys.created.join(', ')}]  skipped: [${results.apiKeys.skipped.join(', ')}]`);
263	  console.log(`  Aliases       created: [${results.aliases.created.join(', ')}]  updated: [${results.aliases.updated.join(', ')}]  skipped: [${results.aliases.skipped.join(', ')}]`);
264	
265	  if (!DRY_RUN && results.apiKeys.created.length > 0) {
266	    console.log('\n  ℹ️   Run  npm run config:contentful  to populate .env with the new API tokens.\n');
267	  }
268	
269	  // A failed locale create is caught per-environment so one bad environment doesn't abort the
270	  // rest — but it must not read as success. Locale provisioning now spans six environments
271	  // rather than master alone, and failures cascade: if `en` fails, the nine locales that declare
272	  // `fallbackCode: 'en'` fail too. Exiting 0 there would let a run in which nothing was created
273	  // look identical to a clean one.
274	  if (results.locales.failed.length > 0) {
275	    log.error(
276	      `${results.locales.failed.length} locale(s) failed to create: ${results.locales.failed.join(', ')}. Re-run to retry.`,
277	    );
278	    process.exit(1);
279	  }
280	}
281	
282	main().catch((err) => {
283	  log.error(err.message ?? err);
284	  process.exit(1);
285	});

