// where the local slug and the file/MRT target name diverge — see
// config/production.js and the `push:prod -t production` npm script.
const DEPLOY_TARGET_MAP = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  uat: 'uat',
  staging: 'staging',
  prod: 'production',
};
// Confirmed environment strategy (2026-07-11): single Contentful space, per-tier
// environment id. `prod` is the only tier that doesn't just reuse its own slug.
const CONTENTFUL_ENV_MAP = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  uat: 'uat',
  staging: 'staging',
  prod: 'master',
};
// `validate --live` runs sequentially across all 6 tiers for both checks — a single
// stalled sandbox must fail fast rather than hang the whole command.
const LIVE_CHECK_TIMEOUT_MS = 10_000;

function readEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return null;
  const entries = [];
  for (const raw of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;
    entries.push([line.slice(0, eqIdx).trim(), line.slice(eqIdx + 1).trim()]);
  }
  return entries;
}

// Section headers look like `# ── Commerce / SFCC ───────────────`.
const SECTION_HEADER_RE = /^#\s*──+\s*(.+?)\s*──+\s*$/;
// Scope tags are their own comment line immediately above the KEY=value line
// (not trailing on the same line) — a trailing comment would make a blank
...switchTo...
    `Created ${path.relative(
      ROOT,
      filePath,
    )} — fill in the ${blankCount} blank value(s) before switching to this tier.`,
  );
  return blankCount;
}

function reportCurrent() {
  const current = readEnvFile(path.join(ROOT, '.env'));
  const envName = current?.find(([key]) => key === 'ENVIRONMENT_NAME')?.[1] || '(not set)';
  console.log(`Current tier: ${envName}`);
  printUsage();
}

function printUsage() {
  console.log(`\nAvailable tiers: ${TIERS.join(', ')}`);
  console.log('Usage:');
  console.log('  npm run env                 — report the current tier');
  console.log('  npm run env -- init            — scaffold every .env.shared / .env.<tier> at once,');
  console.log('                                   pull values from GitHub Environments, then');
  console.log('                                   auto-fill Contentful tokens if possible');
