  1	#!/usr/bin/env node
  2	/**
  3	 * Build (or update) the Zimmermann content model as a single, organization-scoped
  4	 * Contentful Environment Template — the mechanism Contentful now expects content
  5	 * models to be authored through, replacing the old per-environment sync.js +
  6	 * migrations/*.mjs pipeline (see scripts/contentful/README.md).
  7	 *
  8	 * Every file in ./content-types/ defines one content type; this script assembles all
  9	 * of them into one EnvironmentTemplate's `entities.contentTypeTemplates`, get-or-creates
 10	 * it by name under CONTENTFUL_ORGANIZATION_ID, and bumps its version. The template
 11	 * itself does not touch any space or environment — see setup/installTemplate.mjs for
 12	 * pushing it into one.
 13	 *
 14	 * Usage:
 15	 *   npm run sync:contentful
 16	 *   npm run sync:contentful -- --version-name "add region/link/footer/uiCopy models"
 17	 */
 18	
 19	'use strict';
 20	
 21	const contentfulManagement = require('contentful-management');
 22	const path = require('path');
 23	const fs = require('fs');
 24	
 25	/**
 26	 * @typedef {Object} FieldDefinition
 27	 * @property {string} id
 28	 * @property {string} name
 29	 * @property {string} type
 30	 * @property {string} [linkType]
 31	 * @property {boolean} [required]
 32	 * @property {boolean} [localized]
 33	 * @property {Record<string, unknown>} [defaultValue]
 34	 * @property {string} [helpText]
 35	 * @property {Array<Record<string, unknown>>} [validations]
 36	 * @property {{type: string, linkType?: string, validations?: Array<Record<string, unknown>>}} [items]
 37	 */
 38	
 39	/**
 40	 * @typedef {Object} ContentTypeDefinition
 41	 * @property {string} id
 42	 * @property {string} name
 43	 * @property {string} [displayField]
 44	 * @property {string} [description]
 45	 * @property {FieldDefinition[]} fields
 46	 */
 47	
 48	const REQUIRED_ENV = ['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_ORGANIZATION_ID'];
 49	
 50	// The one EnvironmentTemplate this repo owns. Looked up by name (get-or-create) rather
 51	// than a stored ID, matching the get-or-create idiom the rest of this pipeline already
 52	// uses — no ID to keep in sync across machines/CI.
 53	const TEMPLATE_NAME = 'Zimmermann Content Model';
 54	
 55	function checkEnv() {
 56	  const missing = REQUIRED_ENV.filter((k) => !process.env[k]);
 57	  if (missing.length) {
 58	    console.error(`\n❌  Missing env vars: ${missing.join(', ')}`);
 59	    console.error('   Add them to .env (at repo root) and re-run.\n');
 60	    process.exit(1);
 61	  }
 62	}
 63	
 64	function getArg(flag) {
 65	  const args = process.argv.slice(2);
 66	  const i = args.indexOf(flag);
 67	  return i !== -1 ? args[i + 1] : null;
 68	}
 69	
 70	/**
 71	 * Build a Content Type Template field payload. Same shape as a plain content-type
 72	 * field, `localized` just needs to be explicit now — there is no longer a migration
 73	 * file layered on top to override an inferior default.
 74	 * @param {FieldDefinition} def
 75	 */
 76	function buildField(def) {
 77	  /** @type {Record<string, unknown>} */
 78	  const field = {
 79	    id: def.id,
 80	    name: def.name,
 81	    type: def.type,
 82	    required: def.required ?? false,
 83	    localized: def.localized ?? false,
 84	    validations: def.validations ?? [],
 85	  };
 86	  if (def.linkType) field.linkType = def.linkType;
 87	  if (def.items) field.items = def.items;
 88	  if (def.defaultValue) field.defaultValue = def.defaultValue;
 89	  return field;
 90	}
 91	
 92	/** @param {ContentTypeDefinition} def */
 93	function buildContentTypeTemplate(def) {
 94	  return {
 95	    id: def.id,
 96	    name: def.name,
 97	    displayField: def.displayField,
 98	    description: def.description ?? '',
 99	    fields: def.fields.map(buildField),
100	  };
101	}
102	
103	async function main() {
104	  checkEnv();
105	
106	  const organizationId = process.env.CONTENTFUL_ORGANIZATION_ID;
107	  const versionName = getArg('--version-name') ?? new Date().toISOString();
108	  const versionDescription = getArg('--version-description') ?? undefined;
109	
110	  const client = contentfulManagement.createClient(
111	    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
112	    { type: 'plain' },
113	  );
114	
115	  const defsDir = path.join(__dirname, 'content-types');
116	  const files = fs
117	    .readdirSync(defsDir)
118	    .filter((f) => f.endsWith('.js'))
119	    .sort();
120	
121	  if (!files.length) {
122	    console.log('No content type definitions found in scripts/contentful/content-types/');
123	    return;
124	  }
125	
126	  const contentTypeTemplates = files.map((file) => {
127	    const def = /** @type {ContentTypeDefinition} */ (require(path.join(defsDir, file)));
128	    console.log(`→ Including "${def.id}" (${file})`);
129	    return buildContentTypeTemplate(def);
130	  });
131	
132	  const { items: existing } = await client.environmentTemplate.getMany({
133	    organizationId,
134	    query: { limit: 100 },
135	  });
136	  const found = existing.find((t) => t.name === TEMPLATE_NAME);
137	
138	  if (!found) {
139	    await client.environmentTemplate.create(
140	      { organizationId },
141	      {
142	        name: TEMPLATE_NAME,
143	        description: 'Zimmermann PWA content model — every content type in one place, installed per environment.',
144	        versionName,
145	        versionDescription,
146	        entities: { contentTypeTemplates, editorInterfaceTemplates: [] },
147	      },
148	    );
149	    console.log(`  ✅  Created EnvironmentTemplate "${TEMPLATE_NAME}"`);
150	    console.log('\n✅  Build complete.\n');
151	    return;
152	  }
153	
154	  found.entities = { contentTypeTemplates, editorInterfaceTemplates: found.entities.editorInterfaceTemplates ?? [] };
155	  found.versionName = versionName;
156	  found.versionDescription = versionDescription;
157	
158	  await client.environmentTemplate.update({ organizationId, environmentTemplateId: found.sys.id }, found);
159	  console.log(`  ♻️   Updated EnvironmentTemplate "${TEMPLATE_NAME}"`);
160	  console.log('\n✅  Build complete. Run `npm run install:contentful -- --target <env>` to push this out.\n');
161	}
162	
163	main().catch((err) => {
164	  console.error('\n❌  Build failed:', err.message ?? err);
165	  process.exit(1);
166	});

