import type { FooterConfigEntry, RegionEntry } from 'app/types/contentful';

/**
 * Storybook-only fixture for `index.stories.tsx`, shaped exactly like a resolved Contentful
 * CDA response for the `footerConfig` content type. FooterContainer (index.tsx's default
 * export) fetches real content instead — this fixture only ever feeds the presentational
 * `Footer` export directly, so stories render offline without a live CMS connection, per
 * components.md's Contentful story-mocking rule.
 */

