    subscribeHeading: 'Keep in Touch',
    subscribeBody: 'Sign up to stay up to date on the latest news from Zimmermann.',
    copyrightOwner: 'Zimmermann',
    // Placeholder contact channels, the same standing as the nav links' href: '#'.
    // SFCC-55 allows them: "for the purpose of this user story we can include whatever
