    phoneHref: 'tel:+61280808080',
    whatsAppHref: 'https://wa.me/61280808080',
    emailHref: 'mailto:care@zimmermann.com',
    navGroups: [
      {
        sys: { id: 'group-about', contentType: { sys: { id: 'footerNavGroup' } } },
        fields: {
          heading: 'About',
          links: [
            {
              sys: { id: 'link-our-story', contentType: { sys: { id: 'link' } } },
              fields: { label: 'Our Story', href: '#' },
