            },
            {
              sys: { id: 'link-careers', contentType: { sys: { id: 'link' } } },
              fields: { label: 'Careers', href: '#' },
            },
            {
              sys: { id: 'link-brand-prot', contentType: { sys: { id: 'link' } } },
              fields: { label: 'Brand Protection', href: '#' },
            },
            {
              sys: { id: 'link-aoc', contentType: { sys: { id: 'link' } } },
              // \u00A0 (non-breaking space) between "of" and "Country" is deliberate. Figma wraps

