export type ContentfulAsset = {
  sys: {
    id: string;
  };
  fields: {
    title: string;
    description?: string;
    file: {
      url: string;
      fileName: string;
      contentType: string;
      details: {
        size: number;
        image?: {
          width: number;
          height: number;
        };
      };
    };
  };
};

export type ContentfulRichText = {
  nodeType: string;
  data: Record<string, unknown>;
  content: ContentfulRichTextNode[];
};

export type ContentfulRichTextNode = {
  nodeType: string;
  value?: string;
  data?: Record<string, unknown>;
  content?: ContentfulRichTextNode[];
  marks?: Array<{
    type: string;
  }>;
};

export type HomepageEntry = {
  sys: {
    id: string;
    contentType: {
      sys: {
        id: 'homepage';
      };
    };
  };
  fields: {
    heroBanner?: ContentfulAsset;
    duplexSection?: ContentfulRichText;
    videoEmbed?: ContentfulAsset;
    productHero?: string;
  };
};

// ---------------------------------------------------------------------------
// Region content type
// Canonical, referenceable region/storefront entity — any content type needing
// region-scoping (link, footerConfig, etc.) references this via a `regions` field
// instead of duplicating a hardcoded site-ID list. Seeded with one entry per SFCC site
// by scripts/contentful/setup/seedRegions.mjs.
// ---------------------------------------------------------------------------

export type RegionEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'region' } };
  };
  fields: {
    /** SFCC site ID (e.g. 'ZimmermannAU') — the canonical join key. */
    siteId: string;
    /** Editor-facing display name (e.g. 'Australia'). Admin label, not shopper-facing. */
    label: string;
    /** Informational only — mirrors the site's primary locale. */
    locale?: string;
  };
};

// ---------------------------------------------------------------------------
// Footer content types

